query get($id: bigint!) {
  mockups(order_by: {position: asc}, where: {product_id: {_eq: $id}}) {
    product_id
    id
    variant_title
    thumbnail
    preview_thumbnail
    type
    preview_url
    __typename
  }
}

query get($id: bigint!) {
  products_by_pk(id: $id) {
    id
    title
    label
    internal_tags
    fulfillment_id
    fulfillment_linked_id
    fulfillment {
      display_name
      name
      __typename
    }
    description
    default_options
    thumbnail
    is_imported
    design_format
    created_at
    campaign_products {
      created_at
      campaign {
        id
        name
        campaign_instances {
          id
          need_sync
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

query getData($limit: Int!) {
  products_connection(
    first: $limit
    where: {status: {_neq: "1"}}
    order_by: {id: desc}
  ) {
    edges {
      cursor
      node {
        id
        fulfillment_id
        mockups(limit: 2, order_by: {position: asc}) {
          preview_thumbnail
          thumbnail
          __typename
        }
        label
        title
        internal_tags
        is_imported
        campaign_products {
          id
          campaign {
            id
            status
            campaign_instances {
              id
              need_sync
              __typename
            }
            __typename
          }
          __typename
        }
        campaign_products
        created_at
        status
        fulfillment {
          display_name
          __typename
        }
        campaign_products_aggregate {
          aggregate {
            count
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
      __typename
    }
    __typename
  }
}

